package com.brainlessmolanisk;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Draws the BELL cue: an outline on the slayer bell in the inventory. */
class BellOverlay extends WidgetItemOverlay
{
	private final BrainlessMolaniskPlugin plugin;
	private final BrainlessMolaniskConfig config;
	private final ItemManager itemManager;

	@Inject
	BellOverlay(BrainlessMolaniskPlugin plugin, BrainlessMolaniskConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (itemId != ItemID.MOLANISK_BELL || plugin.getCue().getKind() != Cue.Kind.BELL || !config.showBell())
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.drawImage(itemManager.getItemOutline(itemId, widgetItem.getQuantity(), config.bellColor()),
			(int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.brainlessmolanisk;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BrainlessMolaniskConfig.GROUP)
public interface BrainlessMolaniskConfig extends Config
{
	String GROUP = "brainlessmolanisk";
	String LEARNED_SPOTS = "learnedSpots";

	/** Ring tiles learned per spawn (SpotBook format). Seeded with the two rings of 2026-10-22. */
	@ConfigItem(keyName = LEARNED_SPOTS, name = "", description = "", hidden = true)
	default String learnedSpots()
	{
		return "2704,5215,0>2705,5216,0;2713,5213,0>2712,5214,0";
	}

	@ConfigItem(keyName = "showAttack", name = "Highlight molanisk", description = "Outline the molanisk to attack", position = 1)
	default boolean showAttack()
	{
		return true;
	}

	@Alpha
	@ConfigItem(keyName = "attackColor", name = "Molanisk colour", description = "Outline colour of the molanisk to attack", position = 2)
	default Color attackColor()
	{
		return Color.CYAN;
	}

	@ConfigItem(keyName = "showStand", name = "Highlight tile", description = "Mark the tile to stand on before ringing", position = 3)
	default boolean showStand()
	{
		return true;
	}

	@Alpha
	@ConfigItem(keyName = "standColor", name = "Tile colour", description = "Colour of the tile to stand on", position = 4)
	default Color standColor()
	{
		return Color.YELLOW;
	}

	@ConfigItem(keyName = "showBell", name = "Highlight bell", description = "Outline the slayer bell when it is time to ring it", position = 5)
	default boolean showBell()
	{
		return true;
	}

	@Alpha
	@ConfigItem(keyName = "bellColor", name = "Bell colour", description = "Outline colour of the slayer bell", position = 6)
	default Color bellColor()
	{
		return Color.GREEN;
	}
}

package com.brainlessmolanisk;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Named;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Brainless Molanisk",
	description = "Highlights the one thing to click next on a molanisk task: the molanisk, the tile, or the slayer bell",
	tags = {"slayer", "molanisk", "bell", "dorgesh-kaan"}
)
public class BrainlessMolaniskPlugin extends Plugin
{
	/**
	 * Ticks all cues but ATTACK stay hidden after a ring, while the molanisk jumps off the wall.
	 * Measured 2026-10-22: the molanisk spawned 5 ticks after the ring click both times.
	 */
	static final int BELL_SETTLE_TICKS = 8;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SceneCueOverlay sceneOverlay;

	@Inject
	private BellOverlay bellOverlay;

	@Inject
	private NoBellOverlay noBellOverlay;

	@Inject
	@Named("developerMode")
	private boolean developerMode;

	@Inject
	private BrainlessMolaniskConfig config;

	@Inject
	private ConfigManager configManager;

	private final Set<TileObject> walls = new HashSet<>();
	private final SpotBook spotBook = new SpotBook();

	/** The wall object of the spawn the STAND or BELL cue points at, for the overlay's outline. */
	@Getter
	private TileObject standWall;

	@Getter
	private Cue cue = Cue.NONE;

	@Getter
	private NPC attackTarget;

	private int lastRingTick = Integer.MIN_VALUE / 2;

	@Provides
	BrainlessMolaniskConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BrainlessMolaniskConfig.class);
	}

	@Override
	protected void startUp()
	{
		spotBook.load(config.learnedSpots());
		overlayManager.add(sceneOverlay);
		overlayManager.add(bellOverlay);
		overlayManager.add(noBellOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(bellOverlay);
		overlayManager.remove(noBellOverlay);
		if (cue.getKind() == Cue.Kind.STAND && client.hasHintArrow())
		{
			client.clearHintArrow();
		}
		walls.clear();
		cue = Cue.NONE;
		attackTarget = null;
		standWall = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (player == null || wv == null)
		{
			setCue(Cue.NONE, null, null);
			return;
		}

		List<NPC> lured = new ArrayList<>();
		boolean molaniskSeen = false;
		for (NPC npc : wv.npcs())
		{
			if (npc.getId() != NpcID.MOLANISK)
			{
				continue;
			}
			molaniskSeen = true;
			if (!npc.isDead() && (npc.getInteracting() == player || player.getInteracting() == npc))
			{
				lured.add(npc);
			}
		}

		Snapshot.SnapshotBuilder snap = Snapshot.builder()
			.inMolaniskArea(molaniskSeen || !walls.isEmpty())
			.hasBell(hasBell())
			.bellSettling(client.getTickCount() - lastRingTick < BELL_SETTLE_TICKS)
			.player(player.getWorldLocation());
		for (NPC npc : lured)
		{
			snap.luredMolanisk(npc.getWorldLocation());
		}
		for (TileObject wall : walls)
		{
			if (resolvedId(wall) == ObjectID.MOLANISK_ONWALL)
			{
				WorldPoint stand = spotBook.standFor(wall.getWorldLocation(), this::isWalkable);
				if (stand != null)
				{
					snap.holdingSpot(new Spot(wall.getWorldLocation(), stand));
				}
			}
		}

		Cue next = CueEngine.decide(snap.build());
		NPC target = null;
		TileObject wallObject = null;
		if (next.getKind() == Cue.Kind.ATTACK)
		{
			target = lured.stream().filter(n -> n.getWorldLocation().equals(next.getTarget())).findFirst().orElse(null);
		}
		else if (next.getWall() != null)
		{
			wallObject = walls.stream()
				.filter(w -> w.getWorldLocation().equals(next.getWall()) && resolvedId(w) == ObjectID.MOLANISK_ONWALL)
				.findFirst().orElse(null);
		}
		setCue(next, target, wallObject);
	}

	private void setCue(Cue next, NPC target, TileObject wallObject)
	{
		if (developerMode && !next.equals(cue))
		{
			log.info("[BM] cue {} -> {}", cue, next);
		}
		updateHintArrow(cue, next);
		cue = next;
		attackTarget = target;
		standWall = wallObject;
	}

	/** The game's own yellow arrow over the ring tile while walking to it, so a far spawn is findable. */
	private void updateHintArrow(Cue previous, Cue next)
	{
		boolean wanted = next.getKind() == Cue.Kind.STAND && config.showStand();
		boolean had = previous.getKind() == Cue.Kind.STAND;
		if (wanted && !next.getTarget().equals(previous.getTarget()))
		{
			client.setHintArrow(next.getTarget());
		}
		else if (!wanted && had && client.hasHintArrow())
		{
			client.clearHintArrow();
		}
	}

	private boolean hasBell()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		return inv != null && inv.contains(ItemID.MOLANISK_BELL);
	}

	private boolean isWalkable(WorldPoint p)
	{
		WorldView wv = client.getTopLevelWorldView();
		CollisionData[] maps = wv.getCollisionMaps();
		LocalPoint lp = LocalPoint.fromWorld(wv, p);
		if (maps == null || lp == null || p.getPlane() != wv.getPlane())
		{
			return false;
		}
		int flags = maps[p.getPlane()].getFlags()[lp.getSceneX()][lp.getSceneY()];
		return (flags & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0;
	}

	private int resolvedId(TileObject object)
	{
		ObjectComposition comp = client.getObjectDefinition(object.getId());
		if (comp.getImpostorIds() != null)
		{
			comp = comp.getImpostor();
		}
		return comp == null ? -1 : comp.getId();
	}

	private static boolean isMolaniskObject(int id)
	{
		return id >= ObjectID.MOLANISK_NOTONWALL && id <= ObjectID.MOLANISK_CAVEWALL_STONES01;
	}

	private void wallSpawned(TileObject object, String kind)
	{
		if (!isMolaniskObject(object.getId()))
		{
			return;
		}
		walls.add(object);
		if (developerMode)
		{
			log.info("[BM] {} spawned id={} resolved={} at {}", kind, object.getId(), resolvedId(object), object.getWorldLocation());
		}
		if (resolvedId(object) == ObjectID.MOLANISK_NOTONWALL
			&& spotBook.onWallEmptied(client.getTickCount(), object.getWorldLocation()))
		{
			configManager.setConfiguration(BrainlessMolaniskConfig.GROUP, BrainlessMolaniskConfig.LEARNED_SPOTS, spotBook.serialize());
			if (developerMode)
			{
				log.info("[BM] learned ring tile for wall {}: {}", object.getWorldLocation(), spotBook.learnedFor(object.getWorldLocation()));
			}
		}
	}

	private void wallDespawned(TileObject object, String kind)
	{
		if (walls.remove(object) && developerMode)
		{
			log.info("[BM] {} despawned id={} at {}", kind, object.getId(), object.getWorldLocation());
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		wallSpawned(e.getGameObject(), "game");
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned e)
	{
		wallDespawned(e.getGameObject(), "game");
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned e)
	{
		wallSpawned(e.getWallObject(), "wall");
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned e)
	{
		wallDespawned(e.getWallObject(), "wall");
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned e)
	{
		wallSpawned(e.getDecorativeObject(), "decorative");
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned e)
	{
		wallDespawned(e.getDecorativeObject(), "decorative");
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned e)
	{
		wallSpawned(e.getGroundObject(), "ground");
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned e)
	{
		wallDespawned(e.getGroundObject(), "ground");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		// A scene load re-fires every spawn event.
		if (e.getGameState() == GameState.LOADING || e.getGameState() == GameState.LOGIN_SCREEN)
		{
			walls.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (e.getItemId() == ItemID.MOLANISK_BELL && "Ring".equals(e.getMenuOption()))
		{
			lastRingTick = client.getTickCount();
			spotBook.onRing(lastRingTick, client.getLocalPlayer().getWorldLocation());
			if (developerMode)
			{
				log.info("[BM] bell rung at {} tick {}", client.getLocalPlayer().getWorldLocation(), lastRingTick);
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (developerMode && cue.getKind() != Cue.Kind.NONE
			&& (e.getType() == ChatMessageType.GAMEMESSAGE || e.getType() == ChatMessageType.SPAM))
		{
			log.info("[BM] chat {}: {}", e.getType(), e.getMessage());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned e)
	{
		NPC npc = e.getNpc();
		if (developerMode && npc.getId() == NpcID.MOLANISK)
		{
			log.info("[BM] molanisk spawned index={} at {} interacting={}", npc.getIndex(), npc.getWorldLocation(),
				npc.getInteracting() == null ? null : npc.getInteracting().getName());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		NPC npc = e.getNpc();
		if (developerMode && npc.getId() == NpcID.MOLANISK)
		{
			log.info("[BM] molanisk despawned index={} at {} dead={}", npc.getIndex(), npc.getWorldLocation(), npc.isDead());
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		if (developerMode && e.getActor() instanceof NPC && ((NPC) e.getActor()).getId() == NpcID.MOLANISK)
		{
			NPC npc = (NPC) e.getActor();
			log.info("[BM] molanisk index={} anim={} interacting={}", npc.getIndex(), npc.getAnimation(),
				npc.getInteracting() == null ? null : npc.getInteracting().getName());
		}
	}

	@Subscribe
	public void onGraphicsObjectCreated(GraphicsObjectCreated e)
	{
		int id = e.getGraphicsObject().getId();
		if (developerMode && id >= 1029 && id <= 1032)
		{
			log.info("[BM] spotanim {} at {}", id, e.getGraphicsObject().getLocation());
		}
	}
}

package com.brainlessmolanisk;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * The one thing to click next. {@code target} is the molanisk's tile (ATTACK) or the spawn's ring
 * tile (STAND, and BELL when a spawn is known); {@code wall} is that spawn's wall.
 */
@Value
public class Cue
{
	public enum Kind
	{
		NONE,
		NO_BELL,
		ATTACK,
		BELL,
		STAND
	}

	public static final Cue NONE = new Cue(Kind.NONE, null, null);
	public static final Cue NO_BELL = new Cue(Kind.NO_BELL, null, null);
	public static final Cue BELL = new Cue(Kind.BELL, null, null);

	Kind kind;
	WorldPoint target;
	WorldPoint wall;

	static Cue attack(WorldPoint molanisk)
	{
		return new Cue(Kind.ATTACK, molanisk, null);
	}

	static Cue stand(Spot spot)
	{
		return new Cue(Kind.STAND, spot.getStand(), spot.getWall());
	}

	/** The bell, with the spawn it will lure from, so its ring tile stays drawn. */
	static Cue bell(Spot spot)
	{
		return new Cue(Kind.BELL, spot.getStand(), spot.getWall());
	}
}

package com.brainlessmolanisk;

import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.runelite.api.coords.WorldPoint;

/** Picks the single cue to show, in the order attack > bell > stand (REQ-BM-4). Pure: no client calls. */
public final class CueEngine
{
	/** The slayer bell works within this many tiles of the molanisk's wall. */
	static final int BELL_RANGE = 3;

	private CueEngine()
	{
	}

	public static Cue decide(Snapshot s)
	{
		WorldPoint player = s.getPlayer();
		if (!s.isInMolaniskArea() || player == null)
		{
			return Cue.NONE;
		}

		Optional<WorldPoint> molanisk = s.getLuredMolanisks().stream()
			.filter(p -> p.getPlane() == player.getPlane())
			.min(Comparator.comparingInt(player::distanceTo2D));
		if (molanisk.isPresent())
		{
			return Cue.attack(molanisk.get());
		}

		if (!s.isHasBell())
		{
			return Cue.NO_BELL;
		}

		if (s.isBellSettling())
		{
			return Cue.NONE;
		}

		List<Spot> spots = s.getHoldingSpots();
		// No wall state known at all: fall back to the brief's plain rule, the bell after the last molanisk.
		if (spots.isEmpty())
		{
			return Cue.BELL;
		}

		Comparator<Spot> nearest = Comparator.comparingInt(spot -> player.distanceTo2D(spot.getStand()));
		Optional<Spot> inRange = spots.stream().filter(spot -> inBellRange(player, spot.getWall())).min(nearest);
		if (inRange.isPresent())
		{
			return Cue.bell(inRange.get());
		}

		return spots.stream()
			.filter(spot -> spot.getStand().getPlane() == player.getPlane())
			.min(nearest)
			.map(Cue::stand)
			.orElse(Cue.NONE);
	}

	static boolean inBellRange(WorldPoint player, WorldPoint wall)
	{
		return player.getPlane() == wall.getPlane()
			&& Math.max(Math.abs(player.getX() - wall.getX()), Math.abs(player.getY() - wall.getY())) <= BELL_RANGE;
	}
}

package com.brainlessmolanisk;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/** Draws the NO_BELL cue: one line, only inside the molanisk area. */
class NoBellOverlay extends OverlayPanel
{
	private final BrainlessMolaniskPlugin plugin;

	@Inject
	NoBellOverlay(BrainlessMolaniskPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getCue().getKind() != Cue.Kind.NO_BELL)
		{
			return null;
		}
		panelComponent.getChildren().add(LineComponent.builder().left("No slayer bell").leftColor(Color.ORANGE).build());
		return super.render(graphics);
	}
}

package com.brainlessmolanisk;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.ColorUtil;

/** Draws the ATTACK cue (molanisk outline) and the spawn's ring tile, label and wall (STAND and BELL). */
class SceneCueOverlay extends Overlay
{
	private final Client client;
	private final BrainlessMolaniskPlugin plugin;
	private final BrainlessMolaniskConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	SceneCueOverlay(Client client, BrainlessMolaniskPlugin plugin, BrainlessMolaniskConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Cue cue = plugin.getCue();
		if (cue.getKind() == Cue.Kind.ATTACK && config.showAttack())
		{
			NPC npc = plugin.getAttackTarget();
			if (npc != null)
			{
				outlines.drawOutline(npc, 2, config.attackColor(), 4);
			}
		}
		// The ring tile stays drawn while the bell is up, so there is always a ground tile to go by.
		else if ((cue.getKind() == Cue.Kind.STAND || cue.getKind() == Cue.Kind.BELL) && cue.getTarget() != null
			&& config.showStand())
		{
			TileObject wall = plugin.getStandWall();
			if (wall != null)
			{
				outlines.drawOutline(wall, 3, config.standColor(), 4);
			}
			LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), cue.getTarget());
			Polygon poly = lp == null ? null : Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, config.standColor(),
					ColorUtil.colorWithAlpha(config.standColor(), 90), new BasicStroke(3));
				Point text = Perspective.getCanvasTextLocation(client, graphics, lp, "Ring here", 0);
				if (text != null)
				{
					OverlayUtil.renderTextLocation(graphics, text, "Ring here", config.standColor());
				}
			}
		}
		return null;
	}
